export interface OutlineNode {
  readonly id: string;
  readonly label: string;
  readonly children: readonly OutlineNode[];
}

export interface OutlineRow {
  readonly id: string;
  readonly label: string;
  readonly depth: number;
}

export function flattenOutline(forest: readonly OutlineNode[]): readonly OutlineRow[] {
  const rows: OutlineRow[] = [];
  const active = new Set<OutlineNode>();

  const visit = (node: OutlineNode, depth: number): void => {
    if (typeof node.id !== "string" || node.id.trim().length === 0 || typeof node.label !== "string" || node.label.trim().length === 0) {
      throw new TypeError("id and label must be non-blank");
    }
    if (active.has(node)) throw new RangeError("outline contains a cycle");
    active.add(node);
    for (const child of node.children) visit(child, depth + 1);
    rows.push(Object.freeze({ id: node.id, label: node.label, depth }));
    active.delete(node);
  };

  for (const node of forest) visit(node, 0);
  return Object.freeze(rows);
}
```

