import { flattenOutline, type OutlineNode } from './solution';

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}
function equal(actual: unknown, expected: unknown, message: string): void {
  if (actual !== expected) throw new Error(`${message}: expected ${String(expected)}, got ${String(actual)}`);
}
function expectThrows(fn: () => unknown, ctor: typeof TypeError | typeof RangeError, message: string): void {
  try { fn(); } catch (error) { if (error instanceof ctor) return; throw new Error(`${message}: wrong error type`); }
  throw new Error(`${message}: did not throw`);
}

const shared: OutlineNode = { id: 'shared', label: ' Shared ', children: [] };
const forest: OutlineNode[] = [
  {
    id: 'a', label: 'A', children: [
      { id: 'a1', label: 'A1', children: [shared] },
      { id: 'a2', label: 'A2', children: [] },
    ],
  },
  { id: 'b', label: 'B', children: [shared] },
];
const rows = flattenOutline(forest);
const expected = [
  ['a', 'A', 0], ['a1', 'A1', 1], ['shared', ' Shared ', 2],
  ['a2', 'A2', 1], ['b', 'B', 0], ['shared', ' Shared ', 1],
] as const;
equal(rows.length, expected.length, 'row count including repeated shared node');
for (let i = 0; i < expected.length; i += 1) {
  equal(rows[i].id, expected[i][0], `row ${i} id`);
  equal(rows[i].label, expected[i][1], `row ${i} label`);
  equal(rows[i].depth, expected[i][2], `row ${i} depth`);
  assert(Object.isFrozen(rows[i]), `row ${i} is frozen`);
}
assert(Object.isFrozen(rows), 'row array is frozen');

(forest[0] as { label: string }).label = 'changed';
(forest[0].children as OutlineNode[]).push({ id: 'later', label: 'Later', children: [] });
equal(rows[0].label, 'A', 'rows copy node fields');
equal(rows.length, expected.length, 'rows do not alias child arrays');

const empty = flattenOutline([]);
equal(empty.length, 0, 'empty forest');
assert(Object.isFrozen(empty), 'empty forest result is frozen');
expectThrows(() => flattenOutline([{ id: ' ', label: 'x', children: [] }]), TypeError, 'blank id');
expectThrows(() => flattenOutline([{ id: 'x', label: '\t', children: [] }]), TypeError, 'blank label');
expectThrows(() => flattenOutline([{ id: 3, label: 'x', children: [] } as unknown as OutlineNode]), TypeError, 'non-string id');

const cyclic = { id: 'cycle', label: 'Cycle', children: [] as OutlineNode[] };
cyclic.children.push(cyclic);
expectThrows(() => flattenOutline([cyclic]), RangeError, 'direct reference cycle');
const first = { id: 'first', label: 'First', children: [] as OutlineNode[] };
const second = { id: 'second', label: 'Second', children: [first] as OutlineNode[] };
first.children.push(second);
expectThrows(() => flattenOutline([first]), RangeError, 'indirect reference cycle');

